// Package gendocs renders the registered CLI commands and MCP tools as the
// Markdown reference docs docs/commands.md and docs/mcp-tools.md. It reads
// only what package main (cmd/ajent) and internal/mcp already export, so it
// never edits a command or tool definition itself: "make docs" (cmd/ajent
// gendocs, docs/tasks/T7.3.md) is the only writer of the generated files.
package gendocs

import (
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/ajent-social/ajent-client/internal/cli"
	"github.com/ajent-social/ajent-client/internal/mcp"
)

// gendocsGeneratedComment marks both generated files as machine-written.
const gendocsGeneratedComment = "<!-- Generated by `make docs`. Do not edit. -->"

// gendocsNoSummary is the placeholder used for a missing command summary or
// tool description, so a definition without one still renders a row instead
// of failing generation (docs/tasks/T7.3.md, "Out of scope").
const gendocsNoSummary = "(no summary)"

// Commands writes the Markdown command reference for cmds to w: one row per
// non-hidden command, sorted by Name, in a table with columns Command and
// Description. A command with an empty Summary renders gendocsNoSummary
// instead. The output ends with exactly one trailing newline.
func Commands(w io.Writer, cmds []cli.Command) error {
	visible := make([]cli.Command, 0, len(cmds))
	for _, c := range cmds {
		if c.Hidden {
			continue
		}
		visible = append(visible, c)
	}
	sort.Slice(visible, func(i, j int) bool { return visible[i].Name < visible[j].Name })

	var b strings.Builder
	b.WriteString("# Command reference\n\n")
	b.WriteString(gendocsGeneratedComment + "\n\n")
	b.WriteString("| Command | Description |\n")
	b.WriteString("| --- | --- |\n")
	for _, c := range visible {
		summary := c.Summary
		if summary == "" {
			summary = gendocsNoSummary
		}
		fmt.Fprintf(&b, "| `ajent %s` | %s |\n", c.Name, gendocsEscapePipe(summary))
	}
	return gendocsFinish(w, &b)
}

// Tools writes the Markdown MCP tool reference for tools to w: an H1 title,
// then one H2 section per tool with its description paragraph, a
// "Read-only: yes|no. Destructive: yes|no." line, and a "### Input" table
// (columns Field, Type, Required, Description) built from InputSchema. The
// output ends with exactly one trailing newline.
func Tools(w io.Writer, tools []mcp.Tool) error {
	var b strings.Builder
	b.WriteString("# MCP tool reference\n\n")
	b.WriteString(gendocsGeneratedComment + "\n\n")
	for _, t := range tools {
		if err := gendocsWriteTool(&b, t); err != nil {
			return err
		}
	}
	return gendocsFinish(w, &b)
}

// gendocsProperty is the subset of a JSON Schema property gendocsWriteTool
// reads from a tool's InputSchema.
type gendocsProperty struct {
	Type        string `json:"type"`
	Description string `json:"description"`
}

// gendocsInputSchema is the subset of a tool's InputSchema gendocsWriteTool
// decodes: the property definitions and which of them are required.
type gendocsInputSchema struct {
	Properties map[string]gendocsProperty `json:"properties"`
	Required   []string                   `json:"required"`
}

// gendocsWriteTool appends one tool's "## <name>" section to b.
func gendocsWriteTool(b *strings.Builder, t mcp.Tool) error {
	fmt.Fprintf(b, "## %s\n\n", t.Name)

	description := t.Description
	if description == "" {
		description = gendocsNoSummary
	}
	fmt.Fprintf(b, "%s\n\n", description)

	readOnly, destructive := false, false
	if t.Annotations != nil {
		readOnly = t.Annotations.ReadOnlyHint
		destructive = t.Annotations.DestructiveHint
	}
	fmt.Fprintf(b, "Read-only: %s. Destructive: %s.\n\n", gendocsYesNo(readOnly), gendocsYesNo(destructive))

	schema, err := gendocsDecodeSchema(t.InputSchema)
	if err != nil {
		return fmt.Errorf("gendocs: tool %q: %w", t.Name, err)
	}

	required := make(map[string]bool, len(schema.Required))
	for _, name := range schema.Required {
		required[name] = true
	}
	names := make([]string, 0, len(schema.Properties))
	for name := range schema.Properties {
		names = append(names, name)
	}
	sort.Strings(names)

	b.WriteString("### Input\n\n")
	b.WriteString("| Field | Type | Required | Description |\n")
	b.WriteString("| --- | --- | --- | --- |\n")
	for _, name := range names {
		p := schema.Properties[name]
		fmt.Fprintf(b, "| `%s` | %s | %s |%s|\n", name, p.Type, gendocsYesNo(required[name]), gendocsDescriptionCell(p.Description))
	}
	b.WriteString("\n")
	return nil
}

// gendocsDecodeSchema decodes raw (a tool's InputSchema) into its properties
// and required list. An empty schema decodes to the zero value.
func gendocsDecodeSchema(raw json.RawMessage) (gendocsInputSchema, error) {
	var schema gendocsInputSchema
	if len(raw) == 0 {
		return schema, nil
	}
	if err := json.Unmarshal(raw, &schema); err != nil {
		return gendocsInputSchema{}, fmt.Errorf("decoding input schema: %w", err)
	}
	return schema, nil
}

// gendocsYesNo renders b as the "yes"/"no" tokens the reference tables use.
func gendocsYesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

// gendocsEscapePipe escapes a Markdown table cell's literal "|" characters
// so a summary or description containing one cannot break the table.
func gendocsEscapePipe(s string) string {
	return strings.ReplaceAll(s, "|", `\|`)
}

// gendocsFinish writes b's content to w with exactly one trailing LF
// newline, regardless of how many trailing newlines the builder ended with.
func gendocsFinish(w io.Writer, b *strings.Builder) error {
	content := strings.TrimRight(b.String(), "\n") + "\n"
	_, err := io.WriteString(w, content)
	return err
}

func gendocsDescriptionCell(description string) string {
	if description == "" {
		return " "
	}
	return " " + gendocsEscapePipe(description) + " "
}
